// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract OracleHub {
    uint256 public currentEpoch;
    mapping(uint256 => mapping(address => Price)) public prices;

    struct Price {
        uint256 value;
        uint256 timestamp;
    }

    function setPrice(uint256 epochId, address token, uint256 value) external {
        prices[epochId][token] = Price(value, block.timestamp);
    }

    function getPrice(uint256 epochId, address token) external view returns (uint256, uint256) {
        Price memory p = prices[epochId][token];
        return (p.value, p.timestamp);
    }

    function advanceEpoch() external {
        currentEpoch += 1;
    }
}

