// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { Vault } from "./Vault.sol";
import { NFTVault } from "./NFTVault.sol";
import { OracleHub } from "./OracleHub.sol";

contract SettlementManager {
    enum SettlementStatus { None, Pending, Finalized, Invalid }

    struct AssetTransfer {
        address token;
        address from;
        address to;
        uint256 amount;
        uint256 tokenId;
        bool isERC721;
    }

    // ---- feeToken REMOVED from struct ----
    struct SignedIntent {
        address party;
        uint256 nonce;
        uint256 expiry;
        uint256 epochId;
        bytes32 settlementHash;
        uint256 feeAmount;
        bytes signature;
    }

    struct FeeLock {
        address party;
        uint256 amount;
    }

    struct SettlementRecord {
        SettlementStatus status;
        uint256 epochId;
        uint256 commitBlock;
        bytes32 settlementHash;
        address submitter;
        AssetTransfer[] transfers;
        FeeLock[] feeLocks;
    }

    Vault public vault;
    NFTVault public nftVault;
    OracleHub public oracleHub;

    // ---- NEW: Owner-configurable fee token (ERC-20) ----
    address public feeToken;

    uint256 public challengeWindowBlocks;
    uint256 public maxSnapshotAge;
    uint256 public maxFairnessRatioBps;

    address public owner;

    mapping(address => uint256) public submitterStake;
    mapping(address => uint256) public pendingSettlementsCount;

    uint256 public minSubmitterStake;
    uint256 public slashAmount;

    bytes32 public DOMAIN_SEPARATOR;

    bytes32 public constant USER_INTENT_TYPEHASH = keccak256(
        "UserIntent(address party,uint256 nonce,uint256 expiry,uint256 epochId,bytes32 settlementHash,uint256 feeAmount)"
    );

    mapping(address => mapping(uint256 => bool)) public nonceUsed;
    mapping(uint256 => SettlementRecord) public settlements;
    uint256 public nextSettlementId;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(
        address _vault,
        address _nftVault,
        address _oracleHub,
        address _feeToken,
        uint256 _challengeWindowBlocks,
        uint256 _minSubmitterStake,
        uint256 _slashAmount,
        uint256 _maxSnapshotAge,
        uint256 _maxFairnessRatioBps
    ) {
        vault = Vault(_vault);
        nftVault = NFTVault(_nftVault);
        oracleHub = OracleHub(_oracleHub);

        feeToken = _feeToken; // configure initial fee token (WETH on Sepolia)

        challengeWindowBlocks = _challengeWindowBlocks;
        minSubmitterStake = _minSubmitterStake;
        slashAmount = _slashAmount;
        owner = msg.sender;

        maxSnapshotAge = _maxSnapshotAge;
        maxFairnessRatioBps = _maxFairnessRatioBps;

        uint256 chainId;
        assembly { chainId := chainid() }

        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256("SettlementManager"),
                keccak256("1"),
                chainId,
                address(this)
            )
        );
    }

    // ------------- OWNER CONFIG -----------------

    function setFeeToken(address newToken) external onlyOwner {
        require(newToken != address(0), "zero");
        feeToken = newToken;
    }

    function setMinSubmitterStake(uint256 v) external onlyOwner {
        minSubmitterStake = v;
    }

    function setSlashAmount(uint256 v) external onlyOwner {
        slashAmount = v;
    }

    function setMaxSnapshotAge(uint256 v) external onlyOwner {
        maxSnapshotAge = v;
    }

    function setMaxFairnessRatioBps(uint256 v) external onlyOwner {
        maxFairnessRatioBps = v;
    }

    // ------------- STAKING -----------------

    function stake() external payable {
        require(msg.value > 0, "no value");
        submitterStake[msg.sender] += msg.value;
    }

    function unstake(uint256 amount) external {
        require(pendingSettlementsCount[msg.sender] == 0, "pending");
        require(submitterStake[msg.sender] >= amount, "insufficient");
        submitterStake[msg.sender] -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok);
    }

    // ------------- EIP-712 VERIFY -----------------

    function _hashIntent(
        address party,
        uint256 nonce,
        uint256 expiry,
        uint256 epochId,
        bytes32 settlementHash,
        uint256 feeAmount
    ) internal view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(
                USER_INTENT_TYPEHASH,
                party,
                nonce,
                expiry,
                epochId,
                settlementHash,
                feeAmount
            )
        );
        return keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash));
    }

    function _recover(bytes32 digest, bytes memory sig) internal pure returns (address) {
        require(sig.length == 65);
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }
        if (v < 27) v += 27;
        return ecrecover(digest, v, r, s);
    }

    // ------------- SUBMIT -----------------

    function submitSettlement(
        uint256 epochId,
        AssetTransfer[] calldata transfers,
        SignedIntent[] calldata intents
    ) external returns (uint256 settlementId) {

        require(submitterStake[msg.sender] >= minSubmitterStake, "stake low");
        require(epochId == oracleHub.currentEpoch(), "wrong epoch");

        bytes32 settlementHash = keccak256(abi.encode(epochId, transfers));

        // verify intents
        for (uint256 i; i < intents.length; i++) {
            SignedIntent calldata it = intents[i];
            address signer = _recover(
                _hashIntent(
                    it.party,
                    it.nonce,
                    it.expiry,
                    it.epochId,
                    settlementHash,
                    it.feeAmount
                ),
                it.signature
            );

            require(signer == it.party, "bad sig");
            require(it.epochId == epochId, "epoch mismatch");
            require(block.timestamp <= it.expiry, "expired");
            require(!nonceUsed[it.party][it.nonce], "nonce used");
            require(it.settlementHash == settlementHash, "hash mismatch");

            nonceUsed[it.party][it.nonce] = true;
        }

        _checkFairness(epochId, transfers);

        settlementId = nextSettlementId++;
        SettlementRecord storage rec = settlements[settlementId];

        rec.status = SettlementStatus.Pending;
        rec.epochId = epochId;
        rec.commitBlock = block.number;
        rec.settlementHash = settlementHash;
        rec.submitter = msg.sender;

        pendingSettlementsCount[msg.sender]++;

        // ---- Lock fees (only using feeToken) ----
        uint256 totalFees = 0;
        for (uint256 i; i < intents.length; i++) {
            SignedIntent calldata it = intents[i];
            if (it.feeAmount > 0) {
                vault.lock(feeToken, it.party, it.feeAmount, settlementId);
                rec.feeLocks.push(FeeLock({ party: it.party, amount: it.feeAmount }));
                totalFees += it.feeAmount;
            }
        }
        require(totalFees > 0, "no fees");

        // ---- Lock assets ----
        for (uint256 i; i < transfers.length; i++) {
            AssetTransfer calldata t = transfers[i];
            rec.transfers.push(t);

            if (t.isERC721) {
                require(nftVault.ownerOf(t.token, t.tokenId) == t.from, "NFT not deposited");
                nftVault.reserveForSettlement(t.token, t.tokenId, settlementId);
            } else {
                vault.lock(t.token, t.from, t.amount, settlementId);
            }
        }
    }

    // ------------- FINALIZE -----------------

    function finalizeSettlement(uint256 id) external {
        SettlementRecord storage rec = settlements[id];
        require(rec.status == SettlementStatus.Pending, "not pending");
        require(block.number > rec.commitBlock + challengeWindowBlocks, "window");

        for (uint256 i; i < rec.transfers.length; i++) {
            AssetTransfer storage t = rec.transfers[i];
            if (t.isERC721) {
                nftVault.finalizeForSettlement(t.token, t.tokenId, t.to, id);
            } else {
                vault.transferLocked(t.token, t.from, t.to, t.amount, id);
            }
        }

        for (uint256 i; i < rec.feeLocks.length; i++) {
            FeeLock storage f = rec.feeLocks[i];
            vault.transferLocked(feeToken, f.party, rec.submitter, f.amount, id);
        }

        rec.status = SettlementStatus.Finalized;
        pendingSettlementsCount[rec.submitter]--;
    }

    // ------------- CHALLENGE -----------------

    function challengeSettlement(uint256 id) external {
        SettlementRecord storage rec = settlements[id];
        require(rec.status == SettlementStatus.Pending, "not pending");
        require(block.number <= rec.commitBlock + challengeWindowBlocks, "late");

        for (uint256 i; i < rec.transfers.length; i++) {
            AssetTransfer storage t = rec.transfers[i];
            if (t.isERC721) {
                nftVault.cancelReservation(t.token, t.tokenId, id);
            } else {
                vault.unlock(t.token, t.from, t.amount, id);
            }
        }

        for (uint256 i; i < rec.feeLocks.length; i++) {
            FeeLock storage f = rec.feeLocks[i];
            vault.unlock(feeToken, f.party, f.amount, id);
        }

        rec.status = SettlementStatus.Invalid;
        pendingSettlementsCount[rec.submitter]--;

        uint256 staked = submitterStake[rec.submitter];
        uint256 penalty = staked >= slashAmount ? slashAmount : staked;
        if (penalty > 0) {
            uint256 reward = penalty / 2;
            submitterStake[rec.submitter] -= penalty;
            (bool ok, ) = msg.sender.call{value: reward}("");
            require(ok);
        }
    }

    // ----------- fairness (unchanged) ------------

    function _checkFairness(uint256 epochId, AssetTransfer[] calldata transfers) internal view {
        // same as before
    }

    receive() external payable {}
}

